namespace sarif.export.mm;



using ghidra.program.model.address;
using ghidra.program.model.data.ISF;
using ghidra.program.model.mem;
using ghidra.program.model.mem;
using ghidra.program.model.mem;
using sarif.managers;

public class ExtMemoryMap : IsfObject {

	string name;
	string kind;
	string comment;
	bool isVolatile;
	bool isArtificial;
	string type;
	string location;

	public ExtMemoryMap(AddressRange range, MemoryBlock block, MemoryMapBytesFile bf, bool write)
    {

		string permissions = "";
		if (block.isRead()) {
			permissions += "r";
		}
		if (block.isWrite()) {
			permissions += "w";
		}
		if (block.isExecute()) {
			permissions += "x";
		}

		name = block.getName();
		kind = permissions;
		if (block.getComment() != null) {
			comment = block.getComment();
		}
		if (block.isVolatile()) {
			isVolatile = true;
		}
		if (block.isArtificial()) {
			isArtificial = true;
		}
		type = block.getType().name();
		if (block.getType() == MemoryBlockType.BIT_MAPPED ||
			block.getType() == MemoryBlockType.BYTE_MAPPED) {
			// bit mapped blocks can only have one sub-block
			MemoryBlockSourceInfo info = block.getSourceInfos().get(0);
			location = info.getMappedRange().get().getMinAddress().toString();
		}
		else if (block.isInitialized() && write) {
			location = bf.getFileName() + ":" + bf.getOffset();
			bf.writeBytes(range);
		}
	}

}
